#: (table, column) pairs that are genuinely booleans, from rules.boolean_columns().
#: AN ALLOWLIST, and it has to be: `players.intake_path` is declared tinyint(1)
#: and holds 0/1/2/3/9, so a blanket tinyint(1)->boolean rule collapses five
#: states into two, silently, for the values 0 and 1 -- which are most of them.
#: The runtime DDL translator consults this for exactly that reason.
BOOLEAN_COLUMNS = {
    ('discord_links', 'beta_pending'),
    ('gang_vehicles', 'active'),
    ('gang_vehicles', 'alarm'),
    ('offline_msgs', 'delivered'),
    ('players', 'casino_banned'),
    ('players', 'isfirefighter'),
    ('players', 'ismaxtac'),
    ('players', 'isscd'),
    ('players', 'new_player'),
    ('players_global', 'betatester'),
    ('vehicles', 'active'),
    ('vehicles', 'alarm'),
    ('vehicles', 'alive'),
    ('vehicles', 'listed'),
}

#: (table, column) stored as jsonb by the carry-over. The game still writes and
#: reads the `mres` array codec at these, so they need a cast wherever SQL treats
#: them as text -- `COALESCE(wars, '')` against a jsonb column is an error, not a
#: default, and PostgreSQL reports it as invalid JSON rather than a type mismatch.
JSONB_COLUMNS = set()   # empty since 2026-08-20: the codec columns are text (migrate_codec_columns.py); kept as a name because apdb_sql imports it

#: (table, column) declared as an INTEGER type in the target.
#:
#: MariaDB ROUNDS a fractional value into an integer column and says nothing:
#: `fuel='99.9228'` is stored as 100. PostgreSQL refuses the whole statement,
#: so one fractional value in a five-column UPDATE loses the other four writes
#: too -- which is how storing a vehicle left `active` true and the car absent
#: from its owner's garage.
